auto func (auto value){  
    using namespace std;  
    return max({value.size(), (size_t)count_if(value.begin(), value.end(), [](auto x){return isupper(x);}), (size_t)value.max_size()});  
}

auto func (auto value){  
    auto max_length = 0;  
    for (const auto& elem : value) {  
        if (elem.size() > max_length) max_length = elem.size();  
    }  
    return max_length;  
}

